 * and frame scheduling are doubles. Gameplay, story, navigation and save logic
 * are production code. Fixture terminal states are never normal-play evidence. */
import assert from 'node:assert/strict';
import vm from 'node:vm';
import {readFile,mkdir,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {runtime} from '../game/tests/helpers.mjs';
export const plain=x=>JSON.parse(JSON.stringify(x)),KEY='honro-first-act-profile-1';
export async function appHarness({productionStory=false,productionInputActions=false}={}){
 const g=await runtime({legacyMaps:false,productionStory}),storage=new Map(),listeners=new Map(),nodes=new Map();let exported;
 function node(){const classes=new Set();return {innerHTML:'',dataset:{},children:[],hidden:false,isConnected:true,tagName:'BUTTON',style:{setProperty(){}},
 classList:{add:k=>classes.add(k),remove:k=>classes.delete(k),contains:k=>classes.has(k),toggle(k,v){v??=!classes.has(k);v?classes.add(k):classes.delete(k);}},
 querySelector(selector){if(selector==='.training-dialog'&&!this.innerHTML.includes('dialog training-dialog'))return null;return node();},querySelectorAll(){return[];},remove(){},append(){},appendChild(){},insertAdjacentHTML(){},getClientRects(){return[{}];},setAttribute(){},removeAttribute(){},matches(){return true;},focus(){g.document.activeElement=this;},click(){},getContext(){return {translate(){},scale(){},save(){},restore(){},clearRect(){}};},toDataURL(){return'';}};}
 g.document={body:node(),getElementById(id){if(!nodes.has(id))nodes.set(id,node());return nodes.get(id);},querySelector:()=>node(),querySelectorAll:()=>[],createElement:()=>node(),createTreeWalker:()=>({nextNode:()=>false}),addEventListener(type,fn){const set=listeners.get(type)||[];set.push(fn);listeners.set(type,set);}};
 g.window={addEventListener(){}};g.NodeFilter={SHOW_TEXT:4};g.localStorage={getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,v)};g.requestAnimationFrame=()=>0;g.setTimeout=()=>0;g.clearTimeout=()=>{};g.innerWidth=1440;
 g.Blob=Blob;g.URL={createObjectURL(blob){exported=blob;return 'blob:regression';},revokeObjectURL(){}};
 // Model-only DOM double; real camp reconciliation is checked in Chromium.
 g.HonroAudio=class{configure(){}play(){}update(){}};g.HonroScene=class{event(){}focusUnit(){}human(){}};g.HonroCampRenderer={captureFocus:()=>()=>{},patch(root,html){root.innerHTML=html;}};g.HonroUI={camp:()=>'<div id="armory"></div>',bottom:()=>'',portraits:()=>({})};g.HonroUnitInfo={tick(){}};g.HonroPortraits={draw(){}};
 g.HONRO_STORY_PORTRAITS=new Proxy({}, {get:()=>({src:'data:image/png;base64,',class:'archer'})});
 vm.runInContext(await readFile('game/vendor/ui/fa.js','utf8'),g);
 g.HONRO_JOURNEY_MAPS=JSON.parse(await readFile('shared/assets/journey-maps/v1/manifest.json','utf8'));
 for(const file of ['journey-images','journey-art','rest-journey','menu-ui','clear-report-ui','equipment-ui','story','training'])vm.runInContext(await readFile(`shared/runtime/${file}.js`,'utf8'),g);
 if(productionInputActions)vm.runInContext(await readFile('shared/runtime/interactions.js','utf8'),g);
 const source=await readFile('shared/runtime/main.js','utf8'),hook=/    const app=new App\(\),loader=G.HonroCampaignLoader[\s\S]*?(?=    G.HONRO_TOOLS)/;assert.equal((source.match(hook)||[]).length,1);
 let appSource=source.replace(hook,'G.AppRegression={App,fresh};');
 // Keep exact production selection reconciliation at normal HUD call sites.
 // Skip only DOM painting after that prelude; no gameplay state restoration.
 if(productionInputActions){const anchor="            const combatSkills=u.meleeFollow==='ready'";assert.equal(appSource.split(anchor).length,2,'Unique production HUD selection boundary');appSource=appSource.replace(anchor,'            return; // Native harness: HUD DOM paint only is doubled.\n'+anchor);}
 vm.runInContext(appSource,g);const {App,fresh}=g.AppRegression;
 for(const name of ['inputs','updateHUD','updateAudio','updateChargeDisplay','cancelInput','drawPortraits'])if(!(productionInputActions&&['cancelInput','updateHUD'].includes(name)))App.prototype[name]=function(){};
