/** QA fixture-only difficulty correction. No battle writes. */
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
const sha=v=>createHash('sha256').update(typeof v==='string'?v:JSON.stringify(v)).digest('hex');
export function prepareExpeditionFixture(profile,entryDoc,entryRaw){
 assert(entryDoc?.profile&&entryDoc?.battle,'Require preserved original initial artifact, not a continuation');
 assert.equal(profile.settings.difficulty,'normal');assert.equal(profile.settings.debugMode,false);
 const original=JSON.stringify(profile),before=JSON.parse(original);profile.settings.difficulty='story';
 const verify=JSON.parse(JSON.stringify(profile));verify.settings.difficulty='normal';assert.deepEqual(verify,before,'Only one pre-entry setting may change');
 return {originalArtifactSha256:sha(entryRaw),originalProfileSha256:sha(original),expeditionProfileSha256:sha(profile),fixtureDiff:[{path:'settings.difficulty',before:'normal',after:'story'}],training:'Skipped: original prepared legal growth/loadout/gear inherited byte-for-byte apart from difficulty',classification:'New expedition baseline diagnostic; previous tactical fixture kept separate'};
}
export function verifyExpeditionEntry(C,b,profile,entryDoc,tuning){
 assert.equal(profile.settings.difficulty,'story');assert.equal(b.difficulty,'story');
 const d=C.DIFFICULTIES.story,old=C.DIFFICULTIES.normal;assert.equal(d.name,'원정');assert.equal(d.hp,1.05);assert.equal(d.damage,.92);assert.equal(old.name,'전술');assert.equal(old.hp,1.30);assert.equal(old.damage,1.16);
 const oldUnits=entryDoc.battle.units;
 const heroes=b.units.filter(u=>u.side===0&&u.id.startsWith('p-')).map(u=>{const prior=oldUnits.find(v=>v.id===u.id);assert(prior);const keys=['level','hp','maxHp','loadout','equipmentIds','ranks'];for(const k of keys)assert.deepEqual(JSON.parse(JSON.stringify(u[k])),JSON.parse(JSON.stringify(prior[k])),'Hero entry changed '+u.id+':'+k);return{id:u.id,cls:u.cls,level:u.level,xp:profile.heroes[u.cls].xp,hp:u.hp,maxHp:u.maxHp,loadout:[...u.loadout],equipmentIds:[...(u.equipmentIds||[])],ranks:u.ranks};});
 const enemies=b.units.filter(u=>u.side===1&&!u.honroObjectiveTarget&&u.role!=='dummy').map(u=>{assert(Number.isFinite(u.combatBaseHp)&&Number.isFinite(u.combatBaseAttack),'Missing ordinary enemy base stats '+u.id);const hp=Math.round(u.combatBaseHp*d.hp),attack=u.combatBaseAttack*d.damage;const productionApplications=tuning.forUnit(u),exactApplication=productionApplications.findLast(x=>x.exact&&x.after.maxHp===u.maxHp&&Math.abs(x.after.combatBaseHp-u.combatBaseHp)<1e-8);assert(exactApplication||u.maxHp===hp,'No exact production HP application evidence '+u.id);assert(Math.abs(u.attack-attack)<1e-9,'Expedition damage not applied '+u.id);return{id:u.id,role:u.role,combatBaseHp:u.combatBaseHp,maxHp:u.maxHp,nominalSingleRoundHp:hp,productionApplications,hpVerifiedBy:exactApplication?exactApplication.kind:'direct final base round',combatBaseAttack:u.combatBaseAttack,attack:u.attack,expectedAttack:attack};});assert(enemies.length>0);
 return {requestedKey:'story',actualKey:b.difficulty,koreanLabel:d.name,runtimeMultipliers:{hp:d.hp,damage:d.damage,active:d.active,aim:d.aim},actualEnemyLimit:b.enemyLimit,previousMode:{key:'normal',...old},heroes,ordinaryEnemyStatApplications:enemies,allOrdinaryEnemyStatApplicationsVerified:true,method:'Read-only verification after normal App.launch; never called setDifficulty or rewrote battle stats'};
}

export function observeExpeditionTuning(g,C){
 const observations=new WeakMap(),snap=u=>({id:u.id,maxHp:u.maxHp,combatBaseHp:u.combatBaseHp,attack:u.attack,combatBaseAttack:u.combatBaseAttack}),remember=(u,row)=>{const a=observations.get(u)||[];a.push(row);observations.set(u,a);};
 const tune=g.HonroProgression.tuneEnemy;
 g.HonroProgression.tuneEnemy=function(st,u,kind){const result=tune.apply(this,arguments),d=C.DIFFICULTIES[u.honroDifficulty];assert.equal(u.honroDifficulty,'story');const airborne=u.side===1&&!u.summoned&&!u.boss&&!u.honroMidboss&&!u.honroFinalBoss&&['bat','crow'].includes(u.honroVariant||u.honroType),factor=airborne?((u.honroVariant||u.honroType)==='bat'?56/70:70/88):1;const expected=airborne?Math.max(1,Math.round(Math.round(u.combatBaseHp/factor*d.hp)*factor)):Math.round(u.combatBaseHp*d.hp);assert.equal(u.maxHp,expected,'Production difficulty+airborne rounding at tuneEnemy');assert(Math.abs(u.attack-u.combatBaseAttack*d.damage)<1e-9);remember(u,{kind:'production-tuneEnemy',mode:u.honroDifficulty,label:d.name,multipliers:{hp:d.hp,damage:d.damage},airborneFactor:factor,expectedMaxHp:expected,exact:true,after:snap(u)});return result;};
 const encounter=g.HonroAct2.tuneEncounter;
 g.HonroAct2.tuneEncounter=function(u,stage=0){const before=snap(u),tuned=u.honroAct2Tuned,lateTuned=u.honroAct2LateTuned,late=stage>=17&&stage<=20,scales=[];if(!u.honroObjectiveTarget){if(tuned){if(late&&!lateTuned)scales.push(.85);}else{scales.push(.78);if(u.honroAct2Elite&&!u.honroAct2Boss&&u.honroType!=='hoist')scales.push(1.55);if(late)scales.push(.85);}}const result=encounter.apply(this,arguments);const expected=scales.reduce((hp,k)=>Math.max(1,Math.round(hp*k)),before.maxHp);assert.equal(u.maxHp,expected,'Exact production encounter sequential rounding');remember(u,{kind:'production-tuneEncounter',before,hpScaleSequence:scales,expectedMaxHp:expected,exact:true,after:snap(u)});return result;};
 return {forUnit:u=>observations.get(u)||[],scope:'Read-only before/after wrappers call original production functions unchanged; exact difficulty and sequential rounding checked, no HP/stat assignments'};
}

